INSERT INTO vehicles (id, slug, title, brand, model, year, mileage_km, power_ps, power_kw, displacement_cc, engine_type, transmission, drivetrain, fuel_type, exterior_color, interior_color, price_cents, price_on_request, vat_deductible, status, featured, summary, description, highlights_json, mobile_de_url, sort_order, created_at, updated_at) VALUES (1, 'lamborghini-murcielago-6-2-v12', 'Lamborghini Murciélago 6.2 V12 Coupé', 'Lamborghini', 'Murciélago', 2003, 34800, 580, 426, 6192, '6,2 l V12-Saugmotor (60° Bankwinkel)', 'Automatik / E-Gear', 'Permanenter Allradantrieb (VT)', 'Benzin', 'Nero Aldebaran Metallic', 'Vollleder Nero Perseus / Kontrastnaht', NULL, 1, 0, 'available', 1, 'Der Lamborghini Murciélago der frühen 2000er – ein zeitloser V12-Supersportwagen mit dem letzten klassischen Bizzarrini-Zwölfzylinderblock.', 'Der Lamborghini Murciélago markiert den Beginn einer neuen Ära in Sant’Agata Bolognese unter der Designsprache von Luc Donckerwolke – und bewahrt zugleich die ungefilterte Seele des klassischen 6,2-Liter-V12-Saugmotors. Dieses gepflegte Exemplar aus der begehrten ersten Serie wurde in unserer Bonner Fachwerkstatt umfassend geprüft und dokumentiert. Scherentüren, variable Lufteinlässe (VACS) und eine kompromisslose Präsenz machen ihn zu einem wertstabilen Sammlerstück erster Güte.', '["Begehrte Erstserie (6,2-Liter-V12 mit 580 PS / 426 kW)","Umfassende technische Durchsicht & Diagnose durch Auto Kremer Bonn","Originales Bordbuch, Servicehistorie & Zweitschlüssel vorhanden","Variable Lufteinlässe (VACS) & klassische Lamborghini-Scherentüren","Differenzbesteuert gemäß § 25a UStG"]', 'https://suchen.mobile.de/fahrzeuge/details.html?id=432623451', 1, '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z');
INSERT INTO vehicle_images (vehicle_id, url, alt, width, height, sort_order) VALUES (1, '/media/vehicles/murcielago-v12-1.avif', 'Lamborghini Murciélago 6.2 V12 Coupé Front-Seitenansicht im Showroom von Auto Kremer', 1280, 854, 1);
INSERT INTO vehicle_images (vehicle_id, url, alt, width, height, sort_order) VALUES (1, '/media/vehicles/murcielago-v12-2.avif', 'Lamborghini Murciélago 6.2 V12 Detail- und Heckansicht', 1280, 854, 2);
