INSERT INTO vehicles (id, slug, title, brand, model, year, mileage_km, power_ps, power_kw, displacement_cc, engine_type, transmission, drivetrain, fuel_type, exterior_color, interior_color, price_cents, price_on_request, vat_deductible, status, featured, summary, description, highlights_json, mobile_de_url, sort_order, created_at, updated_at) VALUES (8, 'referenz-lamborghini-jarama-400-gt', 'Lamborghini Jarama 400 GT (Bertone V12 Gran Turismo)', 'Lamborghini', 'Jarama 400 GT', 1972, 63500, 350, 257, 3929, '3,9 l V12-Saugmotor mit 6 Weber-Doppelvergasern (40 DCOE)', 'Handschaltung', 'Hinterradantrieb', 'Benzin', 'Argento / Klassisch Metallic', 'Vollleder Senape / Schwarz', NULL, 1, 0, 'sold', 0, 'Verkaufter Klassiker: Seltener Marcello-Gandini-Entwurf für Carrozzeria Bertone mit sechs Weber-Doppelvergasern – eines von nur 177 gebauten 400 GT Exemplaren.', 'Der von Marcello Gandini bei Bertone gezeichnete Lamborghini Jarama 400 GT gehörte zu Ferruccio Lamborghinis persönlichen Lieblingsfahrzeugen: ein souveräner 2+2-Gran-Turismo mit verkürztem Espada-Chassis und dem legendären 3,9-Liter-Vier-Nockenwellen-V12. Mit nur 177 produzierten Exemplaren der ersten Serie ist der Jarama heute eine hochgeschätzte Rarität auf internationalen Concours-Veranstaltungen.', '["Nur 177 gefertigte Exemplare der Serie I (Jarama 400 GT)","Klassischer 3,9-Liter-DOHC-V12 mit sechs Weber-40-DCOE-Vergasern","Ikonisches Design von Marcello Gandini (Carrozzeria Bertone) mit halbverdeckten Klappscheinwerfern"]', NULL, 12, '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z');
INSERT INTO vehicle_images (vehicle_id, url, alt, width, height, sort_order) VALUES (8, '/media/vehicles/sold-jarama-1.avif', 'Verkaufter Lamborghini Jarama 400 GT Klassiker bei Auto Kremer Bonn', 1280, 854, 1);
INSERT INTO vehicle_images (vehicle_id, url, alt, width, height, sort_order) VALUES (8, '/media/vehicles/sold-jarama-2.avif', 'Lamborghini Jarama 400 GT Bertone-Linienführung und Campagnolo-Felgen', 1280, 854, 2);
